input.query:
WITH s1 AS (
 SELECT * FROM proteinatlas
 WHERE "Protein class" ILIKE '%Enzymes%'
   AND "RNA tissue specificity" = 'Tissue enriched'
   AND "RNA tissue specific nTPM" LIKE 'Heart muscle:%'
), s2 AS (
 SELECT * FROM s1 WHERE "Secretome location" = 'Secreted to blood'
), s3 AS (
 SELECT * FROM s2 WHERE "Cancer prognostics - Breast Invasive Carcinoma (TCGA)" LIKE 'validated prognostic unfavorable%'
)
SELECT '1 enzymes; tissue-enriched in heart muscle' AS step, count(*) AS n, string_agg(Gene, ', ' ORDER BY Gene) AS genes FROM s1
UNION ALL SELECT '2 additionally secreted to blood', count(*), string_agg(Gene, ', ' ORDER BY Gene) FROM s2
UNION ALL SELECT '3 additionally validated unfavorable BRCA TCGA', count(*), string_agg(Gene, ', ' ORDER BY Gene) FROM s3;
